insert into leagues (
    id,
    code,
    name,
    country,
    tier,
    active,
    scrape_enabled,
    current_season,
    created_at,
    updated_at,
    badge_url,
    logo_url,
    banner_url,
    poster_url,
    trophy_url,
    fanart_url
)
select
    gen_random_uuid(),
    code,
    display_name,
    country,
    tier,
    true,
    false,
    current_season,
    now(),
    now(),
    badge_url,
    logo_url,
    banner_url,
    poster_url,
    trophy_url,
    fanart_url
from verified_leagues
on conflict (code) do update
set name = excluded.name,
    country = excluded.country,
    tier = excluded.tier,
    current_season = excluded.current_season,
    badge_url = coalesce(excluded.badge_url, leagues.badge_url),
    logo_url = coalesce(excluded.logo_url, leagues.logo_url),
    banner_url = coalesce(excluded.banner_url, leagues.banner_url),
    poster_url = coalesce(excluded.poster_url, leagues.poster_url),
    trophy_url = coalesce(excluded.trophy_url, leagues.trophy_url),
    fanart_url = coalesce(excluded.fanart_url, leagues.fanart_url),
    updated_at = now();

