insert into external_source_mappings (
    id,
    source_type,
    entity_type,
    internal_entity_id,
    external_entity_id,
    league_id,
    season,
    status,
    external_name,
    unresolved_reason,
    created_at,
    updated_at
)
select
    gen_random_uuid(),
    'THESPORTSDB',
    'LEAGUE',
    l.id,
    v.external_id,
    l.id,
    null,
    'RESOLVED',
    v.external_name,
    null,
    now(),
    now()
from verified_leagues v
join leagues l on l.code = v.code
on conflict (source_type, entity_type, external_entity_id) do update
set internal_entity_id = excluded.internal_entity_id,
    league_id = excluded.league_id,
    status = 'RESOLVED',
    external_name = excluded.external_name,
    unresolved_reason = null,
    updated_at = now();
